"""Shared LangGraph state definitions."""

from typing import Any, Dict, List, Optional, TypedDict


class ResearchTask(TypedDict):
    """Sub-task allocated by the Planner agent."""

    task_id: str
    description: str
    agent: str
    status: str
    priority: int


class SourceInfo(TypedDict):
    """Metadata and raw excerpt of a retrieved source."""

    url: str
    title: str
    source_type: str
    content: str
    credibility: float


class FindingInfo(TypedDict):
    """Insight generated by an intelligence agent."""

    agent: str
    category: str
    title: str
    content: str
    confidence: float
    evidence_type: str
    sources: List[str]


class ClaimInfo(TypedDict):
    """Factual assertion requiring cross-verification."""

    claim_text: str
    source_agent: str
    verification_status: str
    confidence: float
    evidence: List[str]


class ConflictInfo(TypedDict):
    """Contradiction detected between two claims."""

    claim_a: str
    claim_b: str
    description: str
    resolution: Optional[str]


class OrchestratorState(TypedDict):
    """Shared state for the multi-agent graph orchestrator."""

    # Input
    competitor_name: str
    competitor_urls: List[str]
    query: str
    research_run_id: int

    # Planner output
    research_tasks: List[ResearchTask]

    # Agent outputs
    sources: List[SourceInfo]
    findings: List[FindingInfo]
    product_intel: List[Dict[str, Any]]
    pricing_intel: List[Dict[str, Any]]
    financial_intel: List[Dict[str, Any]]
    news_items: List[Dict[str, Any]]

    # Verification
    claims: List[ClaimInfo]
    conflicts: List[ConflictInfo]

    # Synthesis
    report: Optional[Dict[str, Any]]

    # Progress tracking
    agent_progress: Dict[str, Dict[str, Any]]
    errors: List[str]
    demo_mode: bool
